"use strict";

// The FALSE-AFFECTED control. Here `bail` genuinely IS rebound by a
// destructuring assignment -- `({ bail } = HANDLERS)` -- standing right
// beside an unrelated computed-key statement of exactly the shape RWF-025
// stops recording. Narrowing which identifiers an assignment target
// contributes must not also drop the genuine one: the name `bail` at the
// call site below is NOT provably the `function bail` declared above it,
// so no abrupt-completion cutoff may be claimed from it and the later
// export keeps whatever authority the model already gave it.
//
// If this module's answer ever moves because the genuine mark was lost
// along with the spurious ones, that is the regression this file exists to
// catch.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

function keyFor(fn) {
  return "handler:" + fn.name;
}

const HANDLERS = {
  bail: function replacement() {
    return "harmless";
  },
};
const REGISTRY = { "handler:bail": "registered" };
let seen;

// Unrelated: contributes `seen` only.
({ [keyFor(bail)]: seen } = REGISTRY);
void seen;

// GENUINE: shorthand destructuring rebinds the local binding `bail`.
({ bail } = HANDLERS);

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  bail();
}

module.exports = safeOp;
